static ImFont *pixBFont(int i);
static float pixSize(int i);
static void sameLineFit(float need, float spacing = 8.0f) { ImGui::SameLine(0, spacing + (retro() ? arcSh() : 0.0f)); if(ImGui::GetContentRegionAvail().x < need) ImGui::NewLine(); }	// the arcade buttons carry a pixel shadow to the right: leave room for it
// the width a row of segButton()s will take — measured in the face segButton actually draws with (the pixel
// faces are much wider or narrower than the body font), plus the shadow the last one casts
static float segWidth(const char *a, const char *b = nullptr, const char *c = nullptr)
{
	float pad = ImGui::GetStyle().FramePadding.x * 2.0f;
	if(retro()) ImGui::PushFont(pixBFont(1), pixSize(1));
	float w = ImGui::CalcTextSize(a).x + pad;
	if(b) w += ImGui::CalcTextSize(b).x + pad;
	if(c) w += ImGui::CalcTextSize(c).x + pad;
	if(retro()){ ImGui::PopFont(); w += arcSh(); }
	return w;
}
