// the camera's axis, off centre so it lands in the middle of the preview pane (see worldDraw), in the units
// rw::Camera::viewOffset uses; the helper folds it into the rays we cast back from the cursor
static rw::V2d gWorldOff = { 0.0f, 0.0f };
static inline void worldRayFrac(float u, float v, const rw::V2d &vw, float &xv, float &yv)
{
	xv = (u - 0.5f - 0.5f * gWorldOff.x / vw.x) * 2.0f * vw.x;
	yv = (0.5f - v - 0.5f * gWorldOff.y / vw.y) * 2.0f * vw.y;
}
