struct WorldOverlay { float u, v, u2, v2; int inst, issue, sev; float d, de; rw::V3d pos; float radius; bool edge; };	// d: streaming distance (min of eye / target), de: distance from the eye — what the on-screen size follows	// marker: top (u,v) and base (u2,v2) in image space 0..1; edge = off-screen, pinned to the border
enum { WH_NONE, WH_PROBLEMS, WH_WEIGHT, WH_DRAWDIST, WH_TRIS, WH_IPL, WH_ARCHIVE, WH_VANILLA, WH_LOD, WH_COL, WH_DENSITY, WH_FLAGS, WH_ALPHA, WH_TXD, WH_DISTRICT, WH_PRELIT, WH_NUM };	// 3D model colouring
struct WorldView {
	std::string root; bool built; unsigned snapVersion; bool markersDirty;
	std::vector<WorldInst> insts;				// parallel to GameData::insts
	std::unordered_map<int, WorldModel> models;		// by model id
	std::unordered_map<std::string, WorldTxd> txds;	// by lower-case TXD name
	std::vector<char> lodHidden;
	rw::V3d target; float yaw, pitch, dist; int centeredOn; bool placed; int drag;
	bool flying; rw::V3d flyTarget; float flyDist;	// camera flight (double click on a marker, a new selection)
	struct Box { float u[8], v[8]; bool ok[8]; };
	std::vector<Box> selBoxes;				// the selected row's placements, as projected boxes
	int rowEmph;						// the row whose placements are emphasised in 3D (ring / boxes / COL); -1 after a click on nothing
	bool showInteriors; float lodFactor; float aspect; int viewW, viewH;	// the view's pixel size last frame — the render target follows it
	int iplFilter;				// GameData::ipls index: only this file's placements are shown, -1 = all
	int frame, loadedModels, drawn, pending;
	std::vector<WorldOverlay> overlays;
	std::unordered_map<int, ColShape> cols; std::set<int> colFailed;	// collision wireframes by model id (selected model only)
	int picked, hoverInst;						// instance under the cursor (ray vs bounding spheres) / clicked one
	rw::V3d hoverPoint; bool hoverPointOk;				// where that ray hit — a spline node is placed there
	Box pickBox; bool pickBoxOk;
	WorldOverlay pickOv; bool pickOvOk;				// the picked model's marker: top / base projected like the row markers
	char findBuf[64];
	int streamInsts; double streamMb, residentMb; int streamFrame;	// «нагрузка здесь»: placements within draw distance of the target and their unique DFF+TXD bytes
	int heat;						// model colouring: 0 textured, 1 by worst row (green = no rows), 2 by DFF+TXD weight
	std::unordered_map<int, WorldColMesh> colMeshes; int colPending, colDrawn; bool gridThru;	// the solid COL meshes by model id; meshes still to build / copies drawn this frame; gridThru: the COL grid through the geometry (ini gridthru=), off = depth-tested on the faces
	int colMode;						// COL wireframe in 3D: 0 off, 1 the selected model's placements, 2 every drawn model (ini col3d=); the toolbar's «COL» toggles 0 ↔ 2
	bool showDff, showLod, showTex, wholeMap;		// the toolbar's «DFF» (ordinary models), «LOD» (LOD models), «TXD» (textures; off = grey models) (ini dff3d= lod3d= txd3d=); wholeMap: LOD models at any distance (ini whole3d=)
	bool tcOn; float tcHour; int tcWeather; float tcApplied; bool tcFilter, tcFog; bool postShown;	// tcFilter: the PC colour filter (CPostEffects::ColourFilter), tcFog: fog FogSt..FarClp in the sky-bottom colour; postShown: this frame's image is in gMv.postTex	// timecycle lighting for the 3D map (ini tc= tchour= tcweather=): on, the clock, the weather row; the day→night blend last written into the loaded models
	std::unordered_map<int, float> weightMb;		// per model id, for WH_WEIGHT
	struct LegendRow { ImVec4 col; std::string text; };
	std::vector<LegendRow> legend; int legendMode; std::string legendRoot;	// legend of the categorical modes (IPL / archive / mod)
	std::unordered_map<int, int> catIndex;			// category key → palette index (IPL fileIdx, archive index)
	std::vector<int> density; int densN;			// objects per 50 m cell (WH_DENSITY)
	WorldView() : built(false), snapVersion(0), markersDirty(true), yaw(0.8f), pitch(0.55f), dist(150.0f), centeredOn(-2), placed(false), drag(-1), flying(false), flyDist(0),
	              showInteriors(false), lodFactor(1.0f), aspect(1.0f), viewW(1024), viewH(1024), iplFilter(-1), rowEmph(-1), frame(0), loadedModels(0), drawn(0), pending(0), streamInsts(0), streamMb(0), residentMb(0), streamFrame(-1000), heat(0), colPending(0), colDrawn(0), gridThru(true), colMode(0), showDff(true), showLod(true), showTex(true), wholeMap(false), tcOn(false), tcHour(12.0f), tcWeather(1), tcApplied(0.0f), tcFilter(true), tcFog(true), postShown(false), legendMode(-1), densN(0), picked(-1), hoverInst(-1), hoverPointOk(false), pickBoxOk(false), pickOvOk(false) { target.x = target.y = target.z = 0; hoverPoint.x = hoverPoint.y = hoverPoint.z = 0; findBuf[0] = 0; }
};
static WorldView gWv;
static bool gWvCamDirty; static double gWvCamSaved;	// the 3D camera moved → the ini is rewritten once the mouse is idle (cam3d survives even a crash)
static double gWvTimeRead, gWvTimeTxd, gWvTimeClump;	// self-test: where the load time goes (ms)
static std::string gOutDirBuf;		// the chosen folder (ini outdir=)
static float gDetailsH = 240.0f;	// height of the details pane (draggable splitter, saved in the ini)
// the rest of the layout the user can drag, all in the ini: window rect / maximised, the TXD and IMG list|preview
// splits, the issue table's column widths once the user has dragged them (0 = fit to content)
static int gWinX = -1, gWinY = -1, gWinW = 1360, gWinH = 860, gWinMax = 0;
static float gTxdSplit = 0.5f, gImgSplit = 0.5f;
static float gColUser[3] = { 0, 0, 0 };


// One skin per game: the pause-menu palette of that title.  SA — warm black + the SA orange, HUD
// colours for the levels; VC — night purple + magenta/cyan neon; III — Liberty City navy + gold.
struct Skin {
	ImVec4 accent, accentHi, accentLo;	// selection, progress, the coloured half of the title
	ImVec4 text, dim;
	ImVec4 childBg, frameBg, headerBg, border;
	ImVec4 sev[SEV_NUM];			// info, warning, error, crash
	ImU32 overlay;				// tint laid over the loading-screen art
	ImU32 grad[4];				// fallback gradient (tl, tr, br, bl)
};
