// Amber phosphor terminal: everything in one warm colour on black — bright amber text, dim amber for
// secondary text, 1 px amber outlines with a small radius, black plates. Severity keeps four warm steps
// (crash red-orange, error amber, warning pale, info dim) so the levels still read at a glance.
static Skin gTermSkin;	// filled by termSkinFor() from the phosphor colour picked in the settings
// Phosphor presets (Настройки → «цвет» in the terminal theme, ini `termhue=`): accent, text, and four
// severity colours chosen to stay apart from the text colour of that preset.
enum { HUE_AMBER = 0, HUE_GREEN, HUE_RED, HUE_CYAN, HUE_WHITE, HUE_NUM };
static int gTermHue = HUE_AMBER;
static void termSkinFor(int hue)
{
	struct P { ImVec4 accent, text, sev[4]; };
	static const P presets[HUE_NUM] = {
		{ ImVec4(0.94f, 0.63f, 0.16f, 1), ImVec4(0.96f, 0.70f, 0.28f, 1), { ImVec4(0.55f, 0.68f, 0.80f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.46f, 0.08f, 1), ImVec4(0.96f, 0.24f, 0.22f, 1) } },
		{ ImVec4(0.30f, 0.92f, 0.42f, 1), ImVec4(0.55f, 1.00f, 0.60f, 1), { ImVec4(0.55f, 0.68f, 0.85f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.55f, 0.15f, 1), ImVec4(0.98f, 0.25f, 0.22f, 1) } },
		{ ImVec4(0.96f, 0.28f, 0.24f, 1), ImVec4(1.00f, 0.46f, 0.40f, 1), { ImVec4(0.60f, 0.70f, 0.85f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.68f, 0.25f, 1), ImVec4(1.00f, 0.95f, 0.90f, 1) } },
		{ ImVec4(0.25f, 0.85f, 0.90f, 1), ImVec4(0.55f, 0.95f, 1.00f, 1), { ImVec4(0.50f, 0.58f, 0.66f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.55f, 0.15f, 1), ImVec4(0.98f, 0.25f, 0.22f, 1) } },
		{ ImVec4(0.84f, 0.84f, 0.84f, 1), ImVec4(0.95f, 0.95f, 0.95f, 1), { ImVec4(0.55f, 0.68f, 0.85f, 1), ImVec4(1.00f, 0.90f, 0.40f, 1), ImVec4(1.00f, 0.55f, 0.15f, 1), ImVec4(0.98f, 0.25f, 0.22f, 1) } },
	};
	if(hue < 0 || hue >= HUE_NUM) hue = HUE_AMBER;
	const P &q = presets[hue];
	ImVec4 a = q.accent;
	Skin &t = gTermSkin;
	t.accent = a;
	t.accentHi = ImVec4(a.x * 0.85f + 0.15f, a.y * 0.85f + 0.15f, a.z * 0.85f + 0.15f, 1);
	t.accentLo = ImVec4(a.x * 0.70f, a.y * 0.70f, a.z * 0.70f, 1);
	t.text = q.text;
	t.dim = ImVec4(a.x * 0.64f, a.y * 0.64f, a.z * 0.64f, 1);
	t.childBg = ImVec4(a.x * 0.022f, a.y * 0.022f, a.z * 0.022f, 1);
	t.frameBg = ImVec4(a.x * 0.048f, a.y * 0.048f, a.z * 0.048f, 1);
	t.headerBg = ImVec4(a.x * 0.075f, a.y * 0.075f, a.z * 0.075f, 1);
	t.border = ImVec4(a.x, a.y, a.z, 0.80f);
	for(int i = 0; i < 4; i++) t.sev[i] = q.sev[i];
	t.overlay = IM_COL32(0, 0, 0, 255);
	for(int i = 0; i < 4; i++) t.grad[i] = IM_COL32(0, 0, 0, 255);
}
