// Three looks: THEME_PAUSE = the loading-screen art behind dense dark plates, Russo One for the HUD-like
// bits; THEME_CALM = flat neutral greys, no art, Inter everywhere, the game's accent as the single colour
// (Linear-style); THEME_BLENDER = Blender's own widgets, greys, blue and Inter, game palette ignored.
// THEME_TERM = an amber CRT terminal: monospace JetBrains Mono, one colour on black, outlined boxes,
// optional scanlines (ini `crt=`). Picked in «Настройки…», ini `theme=`.
// THEME_PANEL = a dashboard: navigation in a left sidebar, the levels as big cards, the table and the
// details in rounded cards on a navy ground, blue accent; the flat (calm) widgets and Inter underneath.
// THEME_STUDIO = the search in the header, the preview under the table, a properties / dependencies panel
// with the actions on the right, the counters in the status line; same navy palette as the panel theme.
enum { THEME_PAUSE = 0, THEME_CALM = 1, THEME_BLENDER = 2, THEME_TERM = 3, THEME_PANEL = 4, THEME_STUDIO = 5, THEME_NUM };
