static ImFont *gFontPlate[7]; static const float PLATE_SIZES[7] = { 9, 10, 11, 12, 13, 14, 15 };	// 3D plates shrink with the camera distance: baked sizes
// the plate scale for a marker `de` units from the eye: full size (all text) up to PLATE_NEAR, then the plate folds
// smoothly — shrinks and fades — until PLATE_FAR, where only the dot is left
static const float PLATE_NEAR = 220.0f, PLATE_FAR = 500.0f;	// the user's numbers
static float plateScale(float de) { if(de <= PLATE_NEAR) return 1.0f; if(de >= PLATE_FAR) return 0.0f; return (PLATE_FAR - de) / (PLATE_FAR - PLATE_NEAR); }
static void pushPlateFont(float scale)
{
	float want = 15.0f * scale * gUiScale; int best = 0;
	for(int i = 0; i < 7; i++) if(PLATE_SIZES[i] * gUiScale <= want + 0.01f) best = i;
	ImGui::PushFont(gFontPlate[best], PLATE_SIZES[best] * gUiScale);
}
