static bool retroNavItem(int icon, const char *label, bool on, ImVec2 p, float h, float &w);	// the kit's navbar tab (same section)
static float gStudioHdrY;	// studio: screen y of the header hairline shared by the column, the middle and the panel (the joints line up)
static const float STUDIO_HDR_H = 40.0f;
static bool looksText(const std::vector<uint8_t> &d);
