static int visibleCount(int s) { const Counters &c = gReport.counters; int n = c.bySev[s] - (gOpt.hideVanilla ? c.vanillaBySev[s] : 0); if(!gShowIgnored) n -= gIgnBySev[s] - (gOpt.hideVanilla ? gIgnVanBySev[s] : 0); return n; }
static int visibleCatCount(int k) { const Counters &c = gReport.counters; int n = c.byCat[k] - (gOpt.hideVanilla ? c.vanillaByCat[k] : 0); if(!gShowIgnored) n -= gIgnByCat[k] - (gOpt.hideVanilla ? gIgnVanByCat[k] : 0); return n; }

static ImU32 col32(const ImVec4 &c, float a) { return IM_COL32((int)(c.x * 255), (int)(c.y * 255), (int)(c.z * 255), (int)(a * 255)); }

// ---------------------------------------------- the UI inspector ---
// «Что это?» for any pixel of the interface. While it is on, ImGui hands us every item of the frame (the
// GcInspectCollect hook in imgui.cpp — a local fork change), the inspector picks the smallest one under the
// cursor and shows what it knows: name, window, rectangle, font size, and the neighbours in the same row with
// the gap or the overlap between them. So a complaint about the layout comes with numbers instead of guesses.
struct InspItem { ImGuiID id; ImVec2 mn, mx; const char *win; float font; };
static bool gInspect = false;			// the mode is on (Ctrl+Shift+I, or the console)
static bool gInspPinned = false;		// the pick is frozen (right click), so the panel can be read
static std::vector<InspItem> gInspItems;	// everything drawn this frame
static std::map<ImGuiID, std::string> gInspTags;	// what our own helpers call themselves
struct InspTag { ImVec2 mn, mx; std::string name; };
static std::vector<InspTag> gInspTagList;	// the same names by rectangle, refilled every frame
static InspItem gInspSel;
static std::string gInspPath;			// «##main/propsbody/sbexport» from ImGui's own ID stack
static std::string gInspReport;			// the last report, ready for the clipboard
static std::string gInspClick;			// what the last left click landed on, and what it changed
static std::string gRpDbg, gRpDbg0;		// the panel's own state, for the inspector: which pages the row offers

static void inspectAdd(unsigned int id, const ImVec2 &mn, const ImVec2 &mx, const char *win, float font)
{
	if(gInspItems.size() > 20000) return;
	InspItem it; it.id = (ImGuiID)id; it.mn = mn; it.mx = mx; it.win = win; it.font = font;
	gInspItems.push_back(it);
}
// our widget helpers name themselves: uiTag("кнопка «Экспорт…»") right after the item they drew
static void uiTag(const std::string &what)
{
	if(!gInspect) return;
	ImGuiID id = ImGui::GetItemID();
	if(id) gInspTags[id] = what;
	InspTag t; t.mn = ImGui::GetItemRectMin(); t.mx = ImGui::GetItemRectMax(); t.name = what;
	if(t.mx.x > t.mn.x + 1.0f && gInspTagList.size() < 4000) gInspTagList.push_back(t);
}


// --------------------------------------------------- the arcade look ---
// What is left of the user's RETRO UI KIT once the arcade layout was dropped: the studio layout wears the
// kit's chrome when the «аркада» scheme is picked — square corners, borders in the accent, a pixel shadow
// (a solid offset block, no blur) under the buttons, and the pixel face in headings and counters.

bool gBtnDbg = false; std::string gBtnDbgLog;	// GTACHECK_BTNDBG=1: geometry of every segButton this frame
static float arcBw() { return (float)gBorderW; }				// border weight (Настройки → «толщина линий»)
// a frame that stays inside its rectangle: ImGui centres AddRect's line on the outline, so half of a thick
// border would spill over the neighbouring widget (the user: «кнопки друг на друга заходят»)
static void rectIn(ImDrawList *dl, ImVec2 a, ImVec2 b, ImU32 col, float rounding, ImDrawFlags flags, float th)
{
	if(rounding <= 0.0f){	// square corners: four solid bands on whole pixels — no half-pixel smear
		dl->AddRectFilled(ImVec2(a.x, a.y), ImVec2(b.x, a.y + th), col);
		dl->AddRectFilled(ImVec2(a.x, b.y - th), ImVec2(b.x, b.y), col);
		dl->AddRectFilled(ImVec2(a.x, a.y + th), ImVec2(a.x + th, b.y - th), col);
		dl->AddRectFilled(ImVec2(b.x - th, a.y + th), ImVec2(b.x, b.y - th), col);
		return;
	}
	float h = th * 0.5f;
	dl->AddRect(ImVec2(a.x + h, a.y + h), ImVec2(b.x - h, b.y - h), col, rounding, flags, th);
}
// the frame of one cell of a joined row: the block gets a single outline, neighbours share no partition
static void blockFrame(ImDrawList *dl, ImVec2 a, ImVec2 b, ImU32 col, float rounding, ImDrawFlags corners, float th)
{
	bool edgeL = corners == ImDrawFlags_RoundCornersAll || (corners & ImDrawFlags_RoundCornersLeft) != 0;
	bool edgeR = corners == ImDrawFlags_RoundCornersAll || (corners & ImDrawFlags_RoundCornersRight) != 0;
	if(edgeL && edgeR){ rectIn(dl, a, b, col, rounding, corners, th); return; }
	if(rounding <= 0.0f){	// the same whole-pixel bands as rectIn
		dl->AddRectFilled(ImVec2(a.x, a.y), ImVec2(b.x, a.y + th), col);
		dl->AddRectFilled(ImVec2(a.x, b.y - th), ImVec2(b.x, b.y), col);
		if(edgeL) dl->AddRectFilled(ImVec2(a.x, a.y), ImVec2(a.x + th, b.y), col);
		if(edgeR) dl->AddRectFilled(ImVec2(b.x - th, a.y), ImVec2(b.x, b.y), col);
		return;
	}
	float h = th * 0.5f;
	dl->AddLine(ImVec2(a.x, a.y + h), ImVec2(b.x, a.y + h), col, th);
	dl->AddLine(ImVec2(a.x, b.y - h), ImVec2(b.x, b.y - h), col, th);
	if(edgeL) dl->AddLine(ImVec2(a.x + h, a.y), ImVec2(a.x + h, b.y), col, th);
	if(edgeR) dl->AddLine(ImVec2(b.x - h, a.y), ImVec2(b.x - h, b.y), col, th);
}
// what to write on a solid accent fill: near-black on a light accent (the «бумага» palette), the ground colour on a dark one
static ImVec4 onAccent()
{
	const ImVec4 &a = SA_ORANGE;
	return (0.299f * a.x + 0.587f * a.y + 0.114f * a.z) > 0.6f ? ImVec4(0.08f, 0.07f, 0.06f, 1) : gGroundVec;
}
static float arcSh() { return (2.0f + (float)gBorderW) * gUiScale; }	// the pixel shadow offset grows with it

static void arcPlate(ImDrawList *dl, ImVec2 a, ImVec2 b, ImU32 fill, ImU32 line, bool shadow = true)
{
	if(shadow){
		float o = arcSh();
		dl->AddRectFilled(ImVec2(a.x + o, a.y + o), ImVec2(b.x + o, b.y + o), col32(SA_ORANGE, 0.10f), 0.0f);
	}
	if(fill & IM_COL32_A_MASK) dl->AddRectFilled(a, b, fill, 0.0f);
	if(line & IM_COL32_A_MASK) rectIn(dl, a, b, line, 0.0f, 0, arcBw());
}


static ImVec4 catColour(int k)	// a soft distinct hue per category (golden-angle walk), for the tree icons and the «Тип» column
{
	float h = fmodf(0.08f + (float)k * 0.618034f, 1.0f), r, g, b; ImGui::ColorConvertHSVtoRGB(h, 0.50f, 0.92f, r, g, b);
	return ImVec4(r, g, b, 1);
}

// ---- Blender icons: SVG → RGBA through nanosvg, one texture per (icon, pixel size); the icons are white on
//      transparent, the draw colour tints them. Textures are never destroyed (MANAGED pool survives a Reset).
static std::map<int, rw::Texture*> gIconTex;	// key = icon * 4096 + px; nullptr = failed once, do not retry
static rw::Texture *iconTexture(int icon, int px)
{
	if(icon < 0 || icon >= BI_NUM || px < 4 || px > 512) return nullptr;
	int key = icon * 4096 + px;
	auto it = gIconTex.find(key); if(it != gIconTex.end()) return it->second;
	rw::Texture *tex = nullptr;
	std::string svg = BLENDER_ICONS[icon].svg;	// nsvgParse writes into its buffer
	NSVGimage *im = nsvgParse(&svg[0], "px", 96.0f);
	if(im && im->width > 0 && im->height > 0){
		float scale = (float)px / (im->width > im->height ? im->width : im->height);	// the 16-unit canvas onto px pixels, centred
		std::vector<unsigned char> rgba((size_t)px * px * 4, 0);
		NSVGrasterizer *rast = nsvgCreateRasterizer();
		if(rast){ nsvgRasterize(rast, im, (px - im->width * scale) * 0.5f, (px - im->height * scale) * 0.5f, scale, rgba.data(), px, px, px * 4); nsvgDeleteRasterizer(rast); }
		rw::Image *img = rw::Image::create(px, px, 32);
		if(img){
			img->allocate(); memcpy(img->pixels, rgba.data(), rgba.size());
			rw::Raster *r = rw::Raster::createFromImage(img); img->destroy();
			if(r){ tex = rw::Texture::create(r); if(tex) tex->setFilter(rw::Texture::LINEAR); }
		}
	}
	if(im) nsvgDelete(im);
	gIconTex[key] = tex;
	return tex;
}
// ---- the logo for the window corner: the PNG decoded once, its green (every saturated pixel) turned to the accent's hue —
//      hue replaced, saturation scaled to the accent's, value kept, so the dark plate, the grey lines and the white text stay
static std::map<ImU32, rw::Texture*> gLogoTex;	// by accent colour; nullptr = failed once
static rw::Texture *logoTexture(const ImVec4 &accent)
{
	ImU32 key = ImGui::ColorConvertFloat4ToU32(accent);
	auto it = gLogoTex.find(key); if(it != gLogoTex.end()) return it->second;
	static std::vector<unsigned char> src; static unsigned w = 0, h = 0; static bool tried = false;
	if(!tried){
		tried = true;
		unsigned char *out = nullptr;
		if(lodepng_decode32(&out, &w, &h, logo_png_data, logo_png_size) == 0 && out){ src.assign(out, out + (size_t)w * h * 4); free(out); }
		else { w = h = 0; }
	}
	rw::Texture *tex = nullptr;
	if(w && h){
		float ah, as, av; ImGui::ColorConvertRGBtoHSV(accent.x, accent.y, accent.z, ah, as, av);
		std::vector<unsigned char> px(src);
		for(size_t i = 0; i + 3 < px.size(); i += 4){
			float r = px[i] / 255.0f, g = px[i + 1] / 255.0f, b = px[i + 2] / 255.0f, hh, ss, vv;
			ImGui::ColorConvertRGBtoHSV(r, g, b, hh, ss, vv);
			if(ss < 0.12f || vv < 0.04f) continue;	// black plate, grey lines, white text: untouched
			float s2 = ss * (as / 0.55f); if(s2 > 1) s2 = 1;	// the logo's green sits around S ≈ 0.55
			ImGui::ColorConvertHSVtoRGB(ah, s2, vv, r, g, b);
			px[i] = (unsigned char)(r * 255.0f + 0.5f); px[i + 1] = (unsigned char)(g * 255.0f + 0.5f); px[i + 2] = (unsigned char)(b * 255.0f + 0.5f);
		}
		rw::Image *img = rw::Image::create((rw::int32)w, (rw::int32)h, 32);
		if(img){
			img->allocate(); memcpy(img->pixels, px.data(), px.size());
			rw::Raster *ra = rw::Raster::createFromImage(img); img->destroy();
			if(ra){ tex = rw::Texture::create(ra); if(tex) tex->setFilter(rw::Texture::LINEARMIPLINEAR); }
		}
	}
	gLogoTex[key] = tex;
	return tex;
}
// an icon centred on c, px pixels square, pixel-aligned; false when the texture could not be made (the caller draws its primitives)
static bool drawIcon(ImDrawList *dl, int icon, ImVec2 c, float px, ImU32 col)
{
	int ipx = (int)(px + 0.5f);
	rw::Texture *t = iconTexture(icon, ipx);
	if(!t) return false;
	ImVec2 a(floorf(c.x - ipx * 0.5f), floorf(c.y - ipx * 0.5f));
	dl->AddImage((ImTextureID)(uintptr_t)t, a, ImVec2(a.x + ipx, a.y + ipx), ImVec2(0, 0), ImVec2(1, 1), col);
	return true;
}

#ifdef _WIN32
// Windows picker (IFileDialog): a folder, or a file of the given types; returns false when cancelled.
static bool pickPath(std::string &out, bool folder, const wchar_t *filterName = nullptr, const wchar_t *filterSpec = nullptr)
{
	bool ok = false;
	HRESULT hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED | COINIT_DISABLE_OLE1DDE);
	IFileDialog *dlg = nullptr;
	if(SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&dlg)))){
		DWORD opts = 0; dlg->GetOptions(&opts); dlg->SetOptions(opts | (folder ? FOS_PICKFOLDERS : FOS_FILEMUSTEXIST) | FOS_FORCEFILESYSTEM);
		if(!folder && filterName){ COMDLG_FILTERSPEC spec[1] = { { filterName, filterSpec } }; dlg->SetFileTypes(1, spec); }
		if(SUCCEEDED(dlg->Show(engineOpenParams.window))){
			IShellItem *item = nullptr;
			if(SUCCEEDED(dlg->GetResult(&item))){
				PWSTR path = nullptr;
				if(SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &path))){
					int n = WideCharToMultiByte(CP_UTF8, 0, path, -1, nullptr, 0, nullptr, nullptr);
					std::string s((size_t)(n > 0 ? n - 1 : 0), '\0');
					if(n > 1) WideCharToMultiByte(CP_UTF8, 0, path, -1, &s[0], n, nullptr, nullptr);
					out = s; ok = true;
					CoTaskMemFree(path);
				}
				item->Release();
			}
		}
		dlg->Release();
	}
	if(SUCCEEDED(hr)) CoUninitialize();
	return ok;
}
static bool pickFolder(std::string &out) { return pickPath(out, true); }
static bool pickImageFile(std::string &out) { return pickPath(out, false, L"PNG / TGA / BMP", L"*.png;*.tga;*.bmp"); }
#else
static bool pickFolder(std::string &) { return false; }
static bool pickImageFile(std::string &) { return false; }
#endif

// The kit's button: a solid accent block with a black label and a pixel shadow (its SUCCESS / WARNING /
// DANGER / INFO tiles). Outside the «аркада» scheme this is ImGui::Button unchanged.
static bool btn(const char *label, const ImVec2 &size)
{
	if(!retro()) return ImGui::Button(label, size);
	float w = size.x > 0.0f ? size.x : size.x < 0.0f ? ImGui::GetContentRegionAvail().x + size.x : 0.0f;
	return segButton(label, label, false, ImDrawFlags_RoundCornersAll, true, true, false, w);	// the same plate, border and shadow as a block button
}

// Blender fills a ticked checkbox with its blue and draws the tick white; ImGui only recolours the tick.
static bool checkbox(const char *label, bool *v)
{
	if(!(blender() || term() || retro()) || !*v){ bool r0 = ImGui::Checkbox(label, v); if(gInspect) uiTag(fmt(T("галочка «%s»"), label)); return r0; }
	ImGui::PushStyleColor(ImGuiCol_FrameBg, SA_ORANGE);
	ImGui::PushStyleColor(ImGuiCol_FrameBgHovered, SA_ORANGE_HI);
	ImGui::PushStyleColor(ImGuiCol_FrameBgActive, SA_ORANGE_LO);
	ImGui::PushStyleColor(ImGuiCol_CheckMark, term() ? ImVec4(0, 0, 0, 1) : retro() ? onAccent() : ImVec4(1, 1, 1, 1));	// the terminal / arcade tick is dark on the fill
	bool r = ImGui::Checkbox(label, v);
	ImGui::PopStyleColor(4);
	if(gInspect) uiTag(fmt(T("галочка «%s»"), label));
	return r;
}
// Blender text fields are near-black (#1d1d1d) and dropdowns dark (#282828) on the grey widgets.
static int pushFieldFrame(bool dropdown)
{
	if(!blender() && !term()) return 0;
	ImVec4 a = term() ? ImVec4(0.0f, 0.0f, 0.0f, 1) : dropdown ? ImVec4(0.157f, 0.157f, 0.157f, 1) : ImVec4(0.114f, 0.114f, 0.114f, 1);
	ImGui::PushStyleColor(ImGuiCol_FrameBg, a);
	ImGui::PushStyleColor(ImGuiCol_FrameBgHovered, ImVec4(a.x + 0.04f, a.y + 0.04f, a.z + 0.04f, 1));
	ImGui::PushStyleColor(ImGuiCol_FrameBgActive, ImVec4(a.x - 0.02f, a.y - 0.02f, a.z - 0.02f, 1));
	return 3;
}

// Severity tile: coloured dot · name · count. Click toggles the level in the table.
static void severityTile(int s, ImDrawFlags corners)
{
	bool enabled = s != SEV_INFO || gOpt.reportInfo;
	int count = visibleCount(s);
	std::string name = severityName(s);
	std::string num = enabled ? fmt("%d", count) : "—";
	ImGui::PushFont(headFont(), headSize()); ImVec2 tn = ImGui::CalcTextSize(name.c_str()); ImGui::PopFont();
	ImGui::PushFont(numFont(), numSize()); ImVec2 tc = ImGui::CalcTextSize(num.c_str()); ImGui::PopFont();
	float h = ImGui::GetFrameHeight() + 8.0f;
	float w = 26.0f + tn.x + 12.0f + tc.x + 14.0f;
	ImVec2 p = ImGui::GetCursorScreenPos();
	ImGui::PushID(s);
	bool clicked = ImGui::InvisibleButton("tile", ImVec2(w, h));
	ImGui::PopID();
	if(clicked){ gSevOn[s] = !gSevOn[s]; gFilterDirty = true; }
	bool hovered = ImGui::IsItemHovered();
	bool on = gSevOn[s] && enabled;
	const ImVec4 &col = SEV_COLOR[s];
	ImDrawList *dl = ImGui::GetWindowDrawList();
	float r = artTheme() ? 3.0f : calm() ? 6.0f : 4.0f;
	ImU32 bg = on ? col32(col, artTheme() || term() ? (hovered ? 0.30f : 0.18f) : calm() ? (hovered ? 0.18f : 0.11f) : (hovered ? 0.28f : 0.20f))
	             : IM_COL32(255, 255, 255, blender() ? (hovered ? 56 : 40) : term() ? (hovered ? 14 : 0) : (hovered ? 22 : 10));	// off = an unpressed grey toggle in Blender, an empty outline on the terminal
	ImU32 border = on ? col32(col, artTheme() || term() ? 0.90f : calm() ? 0.45f : 0.70f) : ImGui::GetColorU32(ImGuiCol_Border);
	// one glued block: only the outer corners are rounded, a non-first tile starts 1 px early so the
	// neighbours share a single outline (same idea as segButton)
	ImVec2 q = p; if(!(corners & ImDrawFlags_RoundCornersLeft)) q.x -= 1.0f;
	dl->AddRectFilled(q, ImVec2(p.x + w, p.y + h), bg, r, corners);
	dl->AddRect(q, ImVec2(p.x + w, p.y + h), border, r, corners);
	float cy = p.y + h * 0.5f;
	dl->AddCircleFilled(ImVec2(p.x + 14.0f, cy), 5.0f, on ? col32(col, 1.0f) : IM_COL32(120, 120, 120, 255));
	ImU32 tcol = on ? ImGui::GetColorU32(ImGuiCol_Text) : ImGui::GetColorU32(ImGuiCol_TextDisabled);
	dl->AddText(headFont(), headSize(), ImVec2(p.x + 26.0f, cy - tn.y * 0.5f), tcol, name.c_str());
	dl->AddText(numFont(), numSize(), ImVec2(p.x + 26.0f + tn.x + 12.0f, cy - tc.y * 0.5f), on && count ? col32(col, 1.0f) : tcol, num.c_str());
	if(hovered){
		if(!enabled) uiTip("%s", T("Заметки не собирались: включи «инфо» в настройках и перепроверь."));
		else uiTip("%s", gSevOn[s] ? T("Скрыть этот уровень в таблице") : T("Показать этот уровень в таблице"));
	}
}

// Joined button group (segmented like Blender's toggle rows): each segment draws its own fill and
// outline, the block is rounded only on the corners the caller marks as outside; a non-first segment
// starts 1 px early so neighbours share a single outline.
enum { ICO_SUN, ICO_MOON };
static bool iconButton(const char *id, int icon, bool on, const char *tip);
static bool segButton(const char *id, const char *label, bool on, ImDrawFlags corners, bool first, bool accentOff = false, bool action = false, float width = 0.0f)
{
	ImGuiStyle &st = ImGui::GetStyle();
	if(retro()) ImGui::PushFont(pixBFont(1), pixSize(1));	// the kit letters its buttons in the pixel face
	ImVec2 ts = ImGui::CalcTextSize(label);
	if(retro()) ImGui::PopFont();
	float sh = retro() ? arcSh() : 0.0f;	// the shadow lives inside the item: the plate is that much smaller
	bool lastInBlock = !retro() || corners == ImDrawFlags_RoundCornersAll || (corners & ImDrawFlags_RoundCornersRight) != 0;
	float shX = lastInBlock ? sh : 0.0f;	// only the last plate of a joined block leaves room for the shadow at its right
	ImVec2 size(width > 0.0f ? width : floorf(ts.x + st.FramePadding.x * 2.0f + shX), ImGui::GetFrameHeight());
	ImVec2 p = ImGui::GetCursorScreenPos();
	bool clicked = ImGui::InvisibleButton(id, size);
	bool hovered = ImGui::IsItemHovered(), held = ImGui::IsItemActive();
	ImVec4 acc = SA_ORANGE, fill, text;
	if(blender()){
		fill = on ? (hovered ? SA_ORANGE_HI : acc) : (hovered ? ImVec4(0.40f, 0.40f, 0.40f, 1) : ImGui::GetStyleColorVec4(ImGuiCol_Button));
		text = on ? ImVec4(1, 1, 1, 1) : SA_TEXT;
		if(accentOff && !on){ fill = hovered ? SA_ORANGE_HI : SA_ORANGE_LO; text = ImVec4(1, 1, 1, 1); }
	}else{
		fill = on ? ImVec4(acc.x, acc.y, acc.z, hovered ? 0.45f : calm() ? 0.20f : 0.28f) : (hovered ? ImVec4(acc.x, acc.y, acc.z, 0.30f) : ImVec4(1, 1, 1, 0.06f));
		text = on ? SA_TEXT : SA_DIM;
		if(accentOff && !on){ fill = term() ? ImVec4(acc.x, acc.y, acc.z, hovered ? 0.40f : 0.22f) : hovered ? SA_ORANGE : SA_ORANGE_LO; text = SA_TEXT; }
	}
	if(action && !on){ text = SA_TEXT; fill = hovered ? ImGui::GetStyleColorVec4(ImGuiCol_ButtonHovered) : ImGui::GetStyleColorVec4(ImGuiCol_Button); }	// a plain action, not a toggle
	if(retro()){	// the kit: the picked segment and the primary action are solid with a black label, the rest are
		bool solid = on || accentOff || action;	// opaque dark plates with an accent border and an accent label
		float m = hovered ? 0.22f : 0.10f;	// how much accent is mixed into the dark plate
		fill = solid ? (hovered ? ImVec4(SA_ORANGE_HI.x, SA_ORANGE_HI.y, SA_ORANGE_HI.z, 1.0f) : ImVec4(acc.x, acc.y, acc.z, 1.0f))	// opaque: two translucent plates overlapping at the joint made a bright stripe that read as a border
		             : ImVec4(gGroundVec.x + (acc.x - gGroundVec.x) * m, gGroundVec.y + (acc.y - gGroundVec.y) * m, gGroundVec.z + (acc.z - gGroundVec.z) * m, 1.0f);
		text = solid ? onAccent() : hovered ? SA_ORANGE_HI : SA_ORANGE;
	}
	if(held) fill = blender() ? SA_ORANGE_LO : retro() ? ImVec4(acc.x, acc.y, acc.z, 1.0f) : ImVec4(acc.x, acc.y, acc.z, 0.60f);
	ImDrawList *dl = ImGui::GetWindowDrawList();
	ImVec2 a(floorf(p.x), floorf(p.y)), b(floorf(p.x + size.x - shX), floorf(p.y + size.y - sh));	// the plate on whole pixels; the shadow fills the rest of the item
	// no stepping back onto the neighbour: the plates butt up edge to edge (the previous one ends exactly at p.x).
	// The old overlap existed so two per-button frames would merge into one — blockFrame draws no partition inside
	// a block any more, so all it did was let every button but the first sit two pixels on top of its neighbour.
	extern bool gBtnDbg; extern std::string gBtnDbgLog;
	if(gBtnDbg) gBtnDbgLog += fmt("btn %s p %.1f,%.1f size %.1f,%.1f sh %.1f shX %.1f fh %.1f font %.1f\n", id, p.x, p.y, size.x, size.y, sh, shX, ImGui::GetFrameHeight(), ImGui::GetFontSize());
	static float blockX0 = 0.0f;	// where the current joined block starts: its shadow is drawn once, under the last plate
	if(first) blockX0 = a.x;
	if(retro() && !held){
		if(lastInBlock){	// one shadow for the whole block, drawn as the strip under it and the strip at its right:
			ImU32 shc = col32(acc, 0.18f);	// a full offset copy would be painted over the plates that are already there
			dl->AddRectFilled(ImVec2(blockX0 + sh, b.y), ImVec2(b.x + sh, b.y + sh), shc, 0.0f);
			dl->AddRectFilled(ImVec2(b.x, a.y + sh), ImVec2(b.x + sh, b.y), shc, 0.0f);
		}
	}else if(retro()){ a.x += sh; a.y += sh; b.x += sh; b.y += sh; }	// pressed: the plate sits down on its shadow
	ImDrawFlags fl = corners ? corners : ImDrawFlags_RoundCornersNone;
	dl->AddRectFilled(a, b, ImGui::GetColorU32(fill), st.FrameRounding, fl);
	if(retro()) blockFrame(dl, a, b, col32(acc, hovered ? 1.0f : 0.80f), st.FrameRounding, fl, arcBw());
	else if(corners == ImDrawFlags_RoundCornersAll || (corners & ImDrawFlags_RoundCornersRight) != 0)	// one rounded outline around the whole block, drawn once at its end: per-segment
		rectIn(dl, ImVec2(blockX0, a.y), b, ImGui::GetColorU32(ImGuiCol_Border), st.FrameRounding, ImDrawFlags_RoundCornersAll, 1.0f);	// frames had to be straight lines, and the block lost its rounded corners
	ImVec2 tp(floorf(a.x + (b.x - a.x - ts.x) * 0.5f), floorf(a.y + (b.y - a.y - ts.y) * 0.5f));	// centred in the plate, on whole pixels (the pixel faces smear on a half pixel)
	if(retro()) dl->AddText(pixBFont(1), pixSize(1), tp, ImGui::GetColorU32(text), label);
	else dl->AddText(tp, ImGui::GetColorU32(text), label);
	if(gInspect) uiTag(fmt("%s «%s» [%s]", action || !on ? T("кнопка") : T("вкладка / переключатель"), label, id));
	return clicked;
}
// one button of a joined block of actions: i of n, full frame height (the user: no tiny buttons, related ones together)
static bool groupBtn(int i, int n, const char *id, const char *label, bool accent = false)
{
	if(i) ImGui::SameLine(0, 0);
	ImDrawFlags c = n <= 1 ? ImDrawFlags_RoundCornersAll : i == 0 ? ImDrawFlags_RoundCornersLeft : i == n - 1 ? ImDrawFlags_RoundCornersRight : ImDrawFlags_RoundCornersNone;
	return segButton(id, label, false, c, i == 0, accent, !accent);
}

// Category chips as one joined block: rows are laid out first so the block's outer corners are known;
// wrapped rows sit flush under each other with rounding only on the block's outside.
static void categoryChips(float rowRight)
{
	std::vector<int> cats; std::vector<std::string> labels; std::vector<float> ws;
	float pad = ImGui::GetStyle().FramePadding.x * 2.0f;
	for(int k = 0; k < CAT_NUM; k++){
		int n = visibleCatCount(k);
		if(n <= 0) continue;
		cats.push_back(k);
		labels.push_back(fmt("%s %d", categoryName(k), n));
		ws.push_back(ImGui::CalcTextSize(labels.back().c_str()).x + pad);
	}
	int n = (int)cats.size();
	if(!n) return;
	float startX = ImGui::GetCursorScreenPos().x, x = startX;
	std::vector<int> rowStart(1, 0);
	for(int i = 0; i < n; i++){
		if(i > rowStart.back() && x + ws[(size_t)i] > rowRight){ rowStart.push_back(i); x = startX; }
		x += ws[(size_t)i];
	}
	int nrows = (int)rowStart.size();
	float h = ImGui::GetFrameHeight();
	ImVec2 p0 = ImGui::GetCursorScreenPos();
	ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0, 0));
	for(int r = 0; r < nrows; r++){
		int a = rowStart[(size_t)r], b = r + 1 < nrows ? rowStart[(size_t)r + 1] : n;
		ImGui::SetCursorScreenPos(ImVec2(startX, p0.y + r * h));
		for(int i = a; i < b; i++){
			int k = cats[(size_t)i];
			ImDrawFlags c = 0;
			if(r == 0 && i == a) c |= ImDrawFlags_RoundCornersTopLeft;
			if(r == 0 && i == b - 1) c |= ImDrawFlags_RoundCornersTopRight;
			if(r == nrows - 1 && i == a) c |= ImDrawFlags_RoundCornersBottomLeft;
			if(r == nrows - 1 && i == b - 1) c |= ImDrawFlags_RoundCornersBottomRight;
			ImGui::PushID(k);
			if(segButton("chip", labels[(size_t)i].c_str(), gCatOn[k], c, i == a)){ gCatOn[k] = !gCatOn[k]; gFilterDirty = true; }
			if(ImGui::BeginPopupContextItem("##chipctx")){
				ImGui::PushFont(headFont(), headSize());
				bool full = k == CAT_XREF || k == CAT_QUALITY || k == CAT_LIMIT;
				if(ImGui::MenuItem(full ? T("Перепроверить всё (эта категория зависит от всего)") : fmt(T("Перепроверить только «%s»"), categoryName(k)).c_str(), nullptr, false, gData && gFlagsDone && !gProgress.running)){ startCheckPartial(k); ImGui::CloseCurrentPopup(); }
				if(ImGui::IsItemHovered()) uiTip("%s", T("Заново читается папка и только этот раздел; строки остальных разделов остаются от прошлой проверки"));
				ImGui::PopFont();
				ImGui::EndPopup();
			}
			ImGui::PopID();
			if(ImGui::IsItemHovered()) uiTip("%s", gCatOn[k] ? T("Скрыть категорию (ПКМ — перепроверить только её)") : T("Показать категорию (ПКМ — перепроверить только её)"));
			if(i + 1 < b) ImGui::SameLine();
		}
	}
	ImGui::PopStyleVar();
	ImGui::Spacing();	// the gap below the block (the glued rows added none)
}

// Draggable bar between the table and the details pane.
static void splitter()
{
	float w = ImGui::GetContentRegionAvail().x;
	float sh = retro() ? 14.0f * gUiScale : 7.0f;	// the rule needs air: it used to sit right on the last table row
	ImGui::InvisibleButton("##split", ImVec2(w > 1 ? w : 1, sh));
	bool hot = ImGui::IsItemHovered() || ImGui::IsItemActive();
	if(hot) ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeNS);
	if(ImGui::IsItemActive()){
		gDetailsH -= ImGui::GetIO().MouseDelta.y;
		if(gDetailsH < 90.0f) gDetailsH = 90.0f;
		if(gDetailsH > 600.0f) gDetailsH = 600.0f;
	}
	if(ImGui::IsItemDeactivated()) saveIni();
	ImVec2 a = ImGui::GetItemRectMin(), b = ImGui::GetItemRectMax();
	float th = retro() ? arcBw() : 2.0f;
	float ry = a.y + (sh - th) * 0.5f;	// centred in the strip, so neither the table above nor the panel below touches it
	ImGui::GetWindowDrawList()->AddRectFilled(ImVec2(a.x, ry), ImVec2(b.x, ry + th), hot ? col32(SA_ORANGE, 0.9f) : ImGui::GetColorU32(retro() ? ImGuiCol_Border : ImGuiCol_Separator));
}

static void exportReport(const char *ext)
{
	if(!gData) return;
	std::string base = joinPath(InuDir(gData->root), "report");
	std::lock_guard<std::mutex> lock(gReport.mtx);
	std::string path = base + "." + ext;
	bool ok = strcmp(ext, "txt") == 0 ? ExportTxt(gReport, *gData, path, gOpt.hideVanilla)
	        : strcmp(ext, "html") == 0 ? ExportHtml(gReport, *gData, path, gOpt.hideVanilla, !gShowIgnored)
	        : strcmp(ext, "csv") == 0 ? ExportCsv(gReport, path, gOpt.hideVanilla)
	        : ExportJson(gReport, *gData, path, gOpt.hideVanilla);
	gStatus = (ok ? T("Сохранено: ") : T("Не удалось записать ")) + path;
	gStatusUntil = nowMs() + 5000;
}

