static void lampTestCompare()	// the live preview against the real bake, on the model nearest the lamp
{
	if(gLampLit.empty() || !gData){ mvChkWrite("lamp cmp: nothing lit\n"); return; }
	int id = *gLampLit.begin(), inst = -1;
	for(size_t i = 0; i < gWv.insts.size(); i++) if(gWv.insts[i].valid && gWv.insts[i].id == id){ inst = (int)i; break; }
	std::map<int, std::vector<uint8_t> >::iterator ce = gLampDffCache.find(id);
	if(inst < 0 || ce == gLampDffCache.end()){ mvChkWrite("lamp cmp: no model\n"); return; }
	BakeOptions o = gBake.opt;
	bakeOptionsFromTimecyc(o, gBake.hour, gBake.sunHours);
	std::vector<BakeLight> lamps;
	for(size_t i = 0; i < gMb.setup.lamps.size(); i++) BakeLampLights(gMb.setup.lamps[i], lamps);
	addSplinePreviewLights(lamps);
	float centre[3] = { gWv.insts[(size_t)inst].centre.x, gWv.insts[(size_t)inst].centre.y, gWv.insts[(size_t)inst].centre.z };
	float rad = gWv.insts[(size_t)inst].radius;
	for(size_t k = 0; k < lamps.size(); k++){
		float dx = lamps[k].pos.x - centre[0], dy = lamps[k].pos.y - centre[1], dz = lamps[k].pos.z - centre[2];
		float reach = lamps[k].range + rad;
		if(dx * dx + dy * dy + dz * dz <= reach * reach) o.lights.push_back(lamps[k]);
	}
	float mat[16]; InstMatrixRaw(gData->insts[(size_t)inst], gData->isSA(), mat);
	BakeResult q;
	BakeOptions oq = o; oq.rays = 0; oq.bounce = 0; oq.planarFit = false; oq.smoothIter = 0;
	BakeQuick(ce->second, mat, oq, q);
	// Regression: smoothing with no lamp contribution must preserve every source colour.
	BakeOptions keep = oq; keep.lampsAdd = true; keep.smoothIter = 6; keep.lights.clear();
	BakeResult unchanged; GDff original; std::string parseErr;
	if(BakeQuick(ce->second, mat, keep, unchanged) && ParseDffGeoms(ce->second, original, parseErr)){
		int changed = 0;
		for(size_t gi = 0; gi < original.geoms.size(); gi++){
			const GGeom &g = original.geoms[gi];
			for(size_t vi = 0; vi < g.day.size(); vi++) if(unchanged.geoms[gi].day[vi] != g.day[vi]) changed++;
			for(size_t vi = 0; vi < g.nightCol.size(); vi++) if((unchanged.geoms[gi].night[vi] & 0xFFFFFFu) != (g.nightCol[vi] & 0xFFFFFFu)) changed++;
		}
		mvChkWrite(fmt("lamp preserve: smoothing 6, changed colours %d\n", changed).c_str());
	}
	BakeCfg cfg; cfg.modelId = id; cfg.neighbours = gBake.neighbours; cfg.useCol = gBake.useCol;
	cfg.alphaOcclude = gBake.alphaOcclude; cfg.lodOcclude = gBake.lodOcclude; cfg.radius = o.radius; cfg.radiusFar = o.radiusFar;
	BakeScene scene; float m2[16]; std::map<int, std::vector<uint8_t> > cache; std::map<int, ColShape> colCache;
	bakeGatherFor(cfg, inst, scene, m2, cache, colCache);
	BakeOptions of = o; of.rays = 64;
	BakeResult f;
	BakePrelit(ce->second, m2, scene, of, f);
	const ObjDef *d = gData->findObj(id);
	mvChkWrite(fmt(T("lamp cmp: %s | живой: день %.0f ночь %.0f (%.2f мс) | запечённый: день %.0f ночь %.0f (%.0f мс, соседей %d, лучей %d)\n"),
	               d ? d->name.c_str() : "?", q.meanDay, q.meanNight, q.ms, f.meanDay, f.meanNight, f.ms, scene.models, of.rays).c_str());
}
static void lampTestNear()	// the placements closest to the lamp: name, distance, radius, taken or not
{
	if(gMb.setup.lamps.empty() || !gData) return;
	const BakeLamp &L = gMb.setup.lamps[0];
	struct Near { float d; int inst; };
	std::vector<Near> ns;
	for(size_t i = 0; i < gWv.insts.size(); i++){
		const WorldInst &w = gWv.insts[i];
		if(!w.valid) continue;
		rw::V3d c = w.centre; float rad = w.radius;
		auto mit = gWv.models.find(w.id);
		if(mit != gWv.models.end() && mit->second.clump && mit->second.sphere.radius > 0.0f){ c = worldPoint(w.mat, mit->second.sphere.center); rad = mit->second.sphere.radius; }
		float dx = c.x - L.pos[0], dy = c.y - L.pos[1], dz = c.z - L.pos[2];
		float d = sqrtf(dx * dx + dy * dy + dz * dz) - rad;	// distance to the model's shell
		Near n; n.d = d; n.inst = (int)i; ns.push_back(n);
	}
	std::sort(ns.begin(), ns.end(), [](const Near &a, const Near &b){ return a.d < b.d; });
	for(size_t i = 0; i < ns.size() && i < 12; i++){
		const WorldInst &w = gWv.insts[(size_t)ns[i].inst];
		const ObjDef *d = gData->findObj(w.id);
		auto mit = gWv.models.find(w.id);
		bool loaded = mit != gWv.models.end() && mit->second.clump;
		mvChkWrite(fmt(T("  near: %-22s id %5d до оболочки %7.1f м радиус %6.1f загружена %d взята %d%s\n"),
		               d ? d->name.c_str() : "?", w.id, ns[i].d, loaded ? mit->second.sphere.radius : w.radius,
		               loaded ? 1 : 0, gLampLit.count(w.id) ? 1 : 0, w.isLod ? " LOD" : "").c_str());
	}
}
#include "window_lighting_selftest.h"
static void lampTestLog()
{
	lampTestNear();
	if(getenv("GTACHECK_SPLINETEST")) mvChkWrite(fmt("spline idle: light passes %d cache builds %d selected %d node %d\n", gLampLivePasses, gSplinePreviewBuilds, gMb.selSpline, gMb.selNode).c_str());
	if(getenv("GTACHECK_WINDOWTEST")) windowLightingTest();
	if(getenv("GTACHECK_LAMPCMP")) lampTestCompare();
	if(const char *dir = getenv("GTACHECK_LAMPSAVE")){	// GTACHECK_LAMPSAVE=<dir>: save the setup there and read it back (the file format)
		std::string err;
		bool okS = BakeSetupSave(dir, gMb.setup, err);
		BakeSetup back; bool okL = BakeSetupLoad(dir, back, err);
		mvChkWrite(fmt("lamp file: save %d load %d lamps %d -> %d", okS ? 1 : 0, okL ? 1 : 0, (int)gMb.setup.lamps.size(), (int)back.lamps.size()).c_str());
		if(!back.lamps.empty()){ const BakeLamp &l = back.lamps[0]; mvChkWrite(fmt(" | %s type %d at %.1f,%.1f,%.1f R %.0f str %.2f when %d\n", l.name.c_str(), l.type, l.pos[0], l.pos[1], l.pos[2], l.range, l.strength, l.when).c_str()); }
		else mvChkWrite("\n");
	}
	mvChkWrite(fmt("lamp: lamps %d lit %d verts %d in %.2f ms | mean day %.0f night %.0f | geoms %d skipped %d | night blend %.2f (tcOn %d hour %.1f)\n",
	               (int)gMb.setup.lamps.size(), (int)gLampLit.size(), gLampVerts, gLampMs, gLampMeanDay, gLampMeanNight,
	               gLampGeomsDone, gLampGeomsSkip, gWv.tcApplied, gWv.tcOn ? 1 : 0, gWv.tcHour).c_str());
	for(size_t i = 0; i < gLampWhat.size(); i++) mvChkWrite(fmt("  lit: %s\n", gLampWhat[i].c_str()).c_str());
}
